"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/tooltip.css";
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";
import { cn } from "../../lib/cn";

export function TooltipProvider({ delay = 350, ...props }: TooltipPrimitive.Provider.Props) {
  return <TooltipPrimitive.Provider delay={delay} {...props} />;
}

export function Tooltip(props: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

export function TooltipTrigger(props: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

export type TooltipContentProps = TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "align" | "alignOffset" | "side" | "sideOffset">;

export function TooltipContent({
  className,
  side = "top",
  sideOffset = 6,
  align = "center",
  alignOffset = 0,
  children,
  ...props
}: TooltipContentProps) {
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner
        className="whatiuse-positioner"
        side={side}
        sideOffset={sideOffset}
        align={align}
        alignOffset={alignOffset}
      >
        <TooltipPrimitive.Popup className={cn("whatiuse-tooltip", className)} {...props}>
          {children}
          <TooltipPrimitive.Arrow className="whatiuse-tooltip__arrow" />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-positioner { z-index: var(--whatiuse-layer-flyout); }

.whatiuse-tooltip kbd { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; color: var(--whatiuse-ink-tertiary); font-family: inherit; font-size: 10px; line-height: 1; white-space: nowrap; }

.whatiuse-tooltip { display: flex; align-items: center; gap: 8px; max-width: 240px; padding: 6px 8px; border-radius: 5px; background: var(--whatiuse-inverse); color: var(--whatiuse-on-inverse); font-size: 12px; line-height: 1.35; box-shadow: 0 5px 18px rgba(0, 0, 0, 0.18); transform-origin: var(--transform-origin); transition: opacity var(--whatiuse-flyout-enter-duration) var(--whatiuse-ease-out), transform var(--whatiuse-flyout-enter-duration) var(--whatiuse-ease-out); }

.whatiuse-tooltip[data-starting-style] { opacity: 0; transform: scale(0.96); }

.whatiuse-tooltip[data-ending-style] { opacity: 0; transform: scale(0.98); transition-duration: var(--whatiuse-flyout-exit-duration); }

.whatiuse-tooltip[data-instant] { transition-duration: 0ms; }

.whatiuse-tooltip kbd { padding: 0 3px; border: 1px solid color-mix(in oklch, var(--whatiuse-on-inverse) 24%, transparent); border-radius: 3px; color: color-mix(in oklch, var(--whatiuse-on-inverse) 76%, transparent); }

.whatiuse-tooltip__arrow { width: 8px; height: 4px; fill: var(--whatiuse-inverse); }

:root[data-theme="dark"] .whatiuse-tooltip__arrow { fill: var(--whatiuse-inverse); }

@media (prefers-reduced-motion: reduce) {
.whatiuse-tooltip {
    transition-property: opacity;
    transition-duration: var(--whatiuse-exit-duration);
  }

.whatiuse-tooltip[data-starting-style],
.whatiuse-tooltip[data-ending-style] { transform: none; }
}
}
